 q=b.add(p,k,t,s,[o[i] for i in order],order.index(0),why,[ex[i] for i in order],typ=typ,difficulty=diff,assumptions=assumptions,steps=steps,formulas=forms,conflict=conflict)
 for c in q['citations']:
  c['role']='conflict' if conflict else 'premise' if typ in ['numerical','derivation','scenario'] else role
  c['locator']=f"Lecture 47, physical PDF page {c['physicalPage']}, printed footer {c['physicalPage']-1475}: {t}."
 if primary:q['primaryEvidence']=[{'title':primary[0],'url':primary[1],'locator':primary[2],'checkedAt':'2026-10-19T22:09:00+00:00'}]
 if conflict:quals.append({'questionId':q['id'],'pages':p if isinstance(p,list)else[p],'sourceClaim':conflict,'qualification':why})
 b.save();return q
